+import type {IncomingMessage} from '../../types/messages.js';
+
+const MAX_CONTENT_LENGTH = 10000;
+
+interface ValidationSuccess {
+  valid: true;
+  data: IncomingMessage;
+}
+
+interface ValidationFailure {
+  valid: false;
+  error: string;
+}
+
+export type ValidationResult = ValidationSuccess | ValidationFailure;
+
+export function validateMessage(payload: unknown): ValidationResult {
+  if (typeof payload !== 'object' || payload === null) {
+    return {valid: false, error: 'Message must be an object'};
+  }
+
+  const message = payload as Record<string, unknown>;
+
+  if (typeof message.type !== 'string') {
+    return {valid: false, error: 'Message must have a type field'};
+  }
+
+  // eslint-disable-next-line re-lint/prefer-polymorphism -- discriminated-union narrowing on an untrusted frame (adrs/ADR-006-lint-suppressions.md)
+  switch (message.type) {
+    case 'user_message':
+    case 'send_message':
+      return validateUserMessage(message);
+    case 'ping':
+      return validatePingMessage(message);
+    default:
+      return {valid: false, error: `Unknown message type: ${message.type}`};
+  }
+}
+
+function validateUserMessage(message: Record<string, unknown>): ValidationResult {
+  if (typeof message.content !== 'string') {
+    return {valid: false, error: 'user_message must have content string'};
+  }
+
+  const trimmed = message.content.trim();
+
+  if (trimmed.length === 0) {
+    return {valid: false, error: 'Message content cannot be empty'};
+  }
+
+  if (message.content.length > MAX_CONTENT_LENGTH) {
+    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
+  }
+
+  return {
+    valid: true,
+    data: {
+      type: 'user_message',
+      content: message.content,
+    },
+  };
+}
+
+function validatePingMessage(message: Record<string, unknown>): ValidationResult {
+  if (typeof message.timestamp !== 'number') {
+    return {valid: false, error: 'ping must have timestamp number'};
+  }
+
+  return {
+    valid: true,
+    data: {
+      type: 'ping',
+      timestamp: message.timestamp,
+    },
+  };
+}

/**
 * prefer-polymorphism — a switch or if/else-if chain that dispatches on an
 * object's tag (`node.type`, `this.kind`, `event.type`) is a polymorphic
 * method or lookup table written by hand. Every new variant reopens every
 * such site; putting the behaviour on the variant (or in a table keyed by the
 * tag) closes them.
 *
 * What counts:
 *  - a `SwitchStatement` whose discriminant is a `MemberExpression` with at
 *    least `minCases` non-default cases;
 *  - an if / else-if chain in which at least `minCases` tests compare the
 *    SAME member expression (by source text) to a literal with `===` / `==`.
 *    The chain is counted from its head and reported once, at the head.
 *
 * Dispatch on a bare identifier (`switch (mode)`) is NOT reported: a local
 * enum branch is fine; it is the tag on an object that wants polymorphism.
 * Option `discriminants` narrows the rule to member expressions whose
 * property name is listed (e.g. `["type", "kind"]`); empty means any.
 *
 * Detect-only: the refactor is a design change, not a codemod.
 */
const DEFAULT_MIN_CASES = 3;
const EQUALITY_OPERATORS = new Set(["===", "=="]);
function propertyName(member) {
    if (!member.computed) {
        return member.property.name;
    }
    return member.property.type === "Literal"
        ? String(member.property.value)
        : null;
}
function isDiscriminant(node, discriminants) {
    if (!node || node.type !== "MemberExpression") {
        return false;
    }
    return (discriminants.length === 0 || discriminants.includes(propertyName(node)));
}
function isChainHead(node) {
    const parent = node.parent;
    return !(parent &&
        parent.type === "IfStatement" &&
        parent.alternate === node);
}
function chainTests(head) {
    const tests = [];
    let current = head;
    while (current && current.type === "IfStatement") {
        tests.push(current.test);
        current = current.alternate;
    }
    return tests;
}
function isEqualityTest(test) {
    return (test?.type === "BinaryExpression" && EQUALITY_OPERATORS.has(test.operator));
}
function memberComparedToLiteral(member, literal, discriminants) {
    const isTagComparison = literal.type === "Literal" && isDiscriminant(member, discriminants);
    return isTagComparison ? member : null;
}
function comparedMember(test, discriminants) {
    if (!isEqualityTest(test)) {
        return null;
    }
    const { left, right } = test;
    return (memberComparedToLiteral(left, right, discriminants) ??
        memberComparedToLiteral(right, left, discriminants));
}
function dominantDiscriminant(members, sourceCode) {
    const counts = new Map();
    for (const member of members) {
        const text = sourceCode.getText(member);
        counts.set(text, (counts.get(text) ?? 0) + 1);
    }
    let best = { discriminant: null, count: 0 };
    for (const [discriminant, count] of counts) {
        best = count > best.count ? { discriminant, count } : best;
    }
    return best;
}
const NO_DISPATCH = { discriminant: null, count: 0 };
function switchDispatch(node, discriminants, sourceCode) {
    if (!isDiscriminant(node.discriminant, discriminants)) {
        return NO_DISPATCH;
    }
    const count = node.cases.filter((switchCase) => switchCase.test !== null).length;
    return { discriminant: sourceCode.getText(node.discriminant), count };
}
function ifChainDispatch(node, discriminants, sourceCode) {
    if (!isChainHead(node)) {
        return NO_DISPATCH;
    }
    const members = chainTests(node)
        .map((test) => comparedMember(test, discriminants))
        .filter((member) => member !== null);
    return dominantDiscriminant(members, sourceCode);
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Prefer polymorphism (or a lookup table) to a switch or if/else-if chain that dispatches on an object's tag property",
        },
        schema: [
            {
                type: "object",
                properties: {
                    minCases: { type: "integer", minimum: 2 },
                    discriminants: { type: "array", items: { type: "string" } },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            preferPolymorphism: "{{count}}-way dispatch on '{{discriminant}}'; a lookup table or polymorphic method replaces it",
        },
    },
    create(context) {
        const options = context.options[0] ?? {};
        const minCases = options.minCases ?? DEFAULT_MIN_CASES;
        const discriminants = options.discriminants ?? [];
        const sourceCode = context.sourceCode;
        function reportDispatch(node, { discriminant, count }) {
            if (count < minCases) {
                return;
            }
            context.report({
                node,
                messageId: "preferPolymorphism",
                data: { count: String(count), discriminant },
            });
        }
        return {
            SwitchStatement(node) {
                reportDispatch(node, switchDispatch(node, discriminants, sourceCode));
            },
            IfStatement(node) {
                reportDispatch(node, ifChainDispatch(node, discriminants, sourceCode));
            },
        };
    },
};

/**
 * no-duplicate-code — flags every block jscpd reports as copied from
 * elsewhere in the scanned roots, spanning the whole duplicated range so an
 * editor highlights exactly what was pasted.
 *
 * jscpd is a whole-tree scanner, so one scan per process serves every file:
 * the index is cached per `cwd` + options. An editor ESLint server keeps its
 * process alive across saves, so a rescan happens when the linted file, or
 * the twin of any clone reported in it, has an mtime newer than the cached
 * scan — that is how a just-removed clone stops being reported on BOTH sides
 * without a restart. A clone newly introduced by editing some other file is
 * seen once that file is linted; the file at hand was not part of it before.
 *
 * `roots` are directories: jscpd walks them itself and treats a glob as a
 * path that does not exist, scanning nothing, so a missing root is reported
 * instead of silently passing.
 */
import { statSync } from "node:fs";
import { relative, resolve } from "node:path";
import { resolveJscpdBin, runJscpd } from "./lib/jscpd/runner.mjs";
/** Below this much real code, a match is a shared dependency list with spillover, not duplicated logic. */
const MIN_CODE_LINES = 3;
const IMPORT_LINE = /^(import|export)\b[^;]*(from\s|["'])/;
const CONTINUATION_LINE = /^[\w$*{},\s]*(\}\s*from\s|["']|,)?[;,]?$/;
const scans = new Map();
const reportedUnavailable = new Set();
function cacheKey(cwd, options) {
    return `${cwd}\n${JSON.stringify(options)}`;
}
function scan(cwd, options) {
    const bin = resolveJscpdBin(cwd, options.jscpdBin);
    return runJscpd({
        cwd,
        bin,
        roots: options.roots ?? ["."],
        minTokens: options.minTokens ?? 50,
        minLines: options.minLines,
        mode: options.mode,
        ignore: options.ignore,
        formats: options.formats,
    });
}
function fileChangedSince(filename, startedAt) {
    try {
        return statSync(filename).mtimeMs > startedAt;
    }
    catch {
        return false;
    }
}
function isStale(entry, filename) {
    const startedAt = entry.startedAt ?? 0;
    const twins = (entry.byFile?.get(filename) ?? []).map((clone) => clone.twin.file);
    return [filename, ...twins].some((path) => fileChangedSince(path, startedAt));
}
function scanFor(cwd, options, filename) {
    const key = cacheKey(cwd, options);
    const cached = scans.get(key);
    if (cached && !isStale(cached, filename)) {
        return { key, entry: cached };
    }
    const entry = scan(cwd, options);
    scans.set(key, entry);
    return { key, entry };
}
function reportUnavailable(context, key, error) {
    if (reportedUnavailable.has(key)) {
        return;
    }
    reportedUnavailable.add(key);
    context.report({
        loc: { line: 1, column: 0 },
        messageId: "unavailable",
        data: { error },
    });
}
/** A line that carries no logic of its own: blank, a comment, or part of an import or export-from statement. */
function isDeclarationLine(line, inBlockComment) {
    const text = line.trim();
    if (inBlockComment) {
        return { declaration: true, inBlockComment: !text.includes("*/") };
    }
    if (text.startsWith("/*")) {
        return { declaration: true, inBlockComment: !text.includes("*/") };
    }
    return { declaration: carriesNoLogic(text), inBlockComment: false };
}
function carriesNoLogic(text) {
    const isComment = text.startsWith("//") || text.startsWith("*");
    return (text === "" ||
        isComment ||
        IMPORT_LINE.test(text) ||
        CONTINUATION_LINE.test(text));
}
/**
 * True when the clone carries almost no logic of its own: two modules
 * importing the same things is what sharing a library looks like, and the
 * only way to stop jscpd matching it is a barrel that hides where each
 * symbol comes from, which is a worse file to read. A match runs on past the
 * last import into whatever follows, so a couple of trailing lines are the
 * spillover rather than the duplication.
 */
function isDependencyList(sourceCode, clone) {
    const lines = sourceCode.lines.slice(clone.start.line - 1, clone.end.line);
    let inBlockComment = false;
    let codeLines = 0;
    for (const line of lines) {
        const verdict = isDeclarationLine(line, inBlockComment);
        inBlockComment = verdict.inBlockComment;
        codeLines += verdict.declaration ? 0 : 1;
    }
    return codeLines < MIN_CODE_LINES;
}
function reportClone(context, cwd, clone) {
    context.report({
        loc: { start: clone.start, end: clone.end },
        messageId: "duplicate",
        data: {
            lines: String(clone.lines),
            tokens: String(clone.tokens),
            twin: relative(cwd, clone.twin.file),
            twinStart: String(clone.twin.startLine),
            twinEnd: String(clone.twin.endLine),
        },
    });
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Disallow code blocks that jscpd reports as duplicated elsewhere in the scanned roots",
        },
        schema: [
            {
                type: "object",
                properties: {
                    minTokens: { type: "integer", minimum: 1 },
                    minLines: { type: "integer", minimum: 1 },
                    mode: { enum: ["mild", "weak", "strict"] },
                    ignore: { type: "array", items: { type: "string" } },
                    roots: { type: "array", items: { type: "string" }, minItems: 1 },
                    formats: { type: "array", items: { type: "string" } },
                    jscpdBin: { type: "string" },
                },
                additionalProperties: false,
            },
        ],
        messages: {
            duplicate: "{{lines}} lines ({{tokens}} tokens) duplicated with {{twin}}:{{twinStart}}-{{twinEnd}}",
            unavailable: "jscpd could not run ({{error}}) — install it with `npm i -D jscpd` or point the `jscpdBin` option at its run-jscpd.js",
        },
    },
    create(context) {
        const options = context.options[0] ?? {};
        const cwd = context.cwd;
        const filename = resolve(cwd, context.filename);
        return {
            Program() {
                const { key, entry } = scanFor(cwd, options, filename);
                if (entry.error) {
                    reportUnavailable(context, key, entry.error);
                    return;
                }
                const { sourceCode } = context;
                for (const clone of entry.byFile.get(filename) ?? []) {
                    if (!isDependencyList(sourceCode, clone)) {
                        reportClone(context, cwd, clone);
                    }
                }
            },
        };
    },
};

